/**
 * Contact shadows on a planet — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of the pass below,
 * loaded only by dynamic `import()` from the planet view
 * (contactAndBlur.ts), where the visitor's tier draws contact shadows and the
 * sun casts cascaded shadows.
 *
 * One pass over the whole picture, after the temporal anti-aliasing and
 * before the eye exposes it (screenPasses.ts): each pixel's point is found
 * again from the depth the scene was drawn with, its face from the points
 * about it, and a short march toward the sun over the depth asks whether
 * anything drawn stands in the way (contactShadows.ts has the arithmetic).
 * Where it does, the sun's direct share of the pixel's light is taken away:
 * the sun's light on the face, through the sun's own shadow map, over that
 * and the sky's fill (the scene's hemispheric light) together. So the fill
 * is left as it was, and where the shadow map already says shade nothing is
 * taken. Behind the anti-aliasing the march's samples are shifted each frame
 * and the frames blend them; without it they hold still.
 *
 * The pass is on the camera only while the sun casts cascaded shadows and
 * shines; otherwise the picture is today's. As the other planet passes, it
 * is written in WGSL for WebGPU and GLSL for WebGL2, kept in step.
 */
import { PostProcess } from '@babylonjs/core/PostProcesses/postProcess';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { ShaderStore } from '@babylonjs/core/Engines/shaderStore';
import { Constants } from '@babylonjs/core/Engines/constants';
import { Matrix, Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Effect } from '@babylonjs/core/Materials/effect';
import type { Observer } from '@babylonjs/core/Misc/observable';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { Scene } from '@babylonjs/core/scene';
import type { ShadowGenerator } from '@babylonjs/core/Lights/Shadows/shadowGenerator';
import type { ContactShadowsHandle } from './contactAndBlur';
import { CONTACT } from './contactShadows';
import { depthNdcOf, giveDepthIfFirst, keepInOrder, sceneDepth } from './screenPasses';

const f = (x: number) => (Number.isInteger(x) ? `${x}.0` : String(x));

/** The sun's cascades the pass reads, at most. */
const CASCADES = 4;
const NAME = 'planetContactShadows';

// ---- GLSL (WebGL) ----

const GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
uniform highp sampler2D depthSampler;
uniform highp sampler2DArrayShadow shadowMap;
uniform vec4 lens;
uniform mat4 projection;
uniform mat4 cascades[${CASCADES}];
uniform vec4 splits;
uniform vec3 toSun;
uniform vec3 up;
uniform vec3 light;
uniform vec2 depthNdc;
uniform vec2 zFrom;
uniform vec2 screen;
uniform float halfZ;
uniform float seed;
float depthAt(ivec2 p) { return texelFetch(depthSampler, clamp(p, ivec2(0), textureSize(depthSampler, 0) - 1), 0).r; }
// A point in the eye's space from its place on the screen and its depth, as the perspective projection gives them.
vec3 viewAt(vec2 at, float d) {
  float z = zFrom.y / (d * depthNdc.x + depthNdc.y - zFrom.x);
  return vec3((at * 2.0 - 1.0 - lens.zw) * z / lens.xy, z);
}
vec3 viewAtTexel(ivec2 t, vec2 size) { return viewAt((vec2(t) + 0.5) / size, depthAt(t)); }
void main(void) {
  vec4 colour = texture2D(textureSampler, vUV);
  gl_FragColor = colour;
  vec2 size = vec2(textureSize(depthSampler, 0));
  ivec2 t = ivec2(vUV * size);
  vec3 c = viewAtTexel(t, size);
  if (!(c.z > 0.0 && c.z < ${f(CONTACT.fadeEndM)})) return;
  // The face, from the points about it: on each axis the side nearer in depth, so an edge keeps its own face.
  vec3 r = viewAtTexel(t + ivec2(1, 0), size);
  vec3 l = viewAtTexel(t - ivec2(1, 0), size);
  vec3 u = viewAtTexel(t + ivec2(0, 1), size);
  vec3 b = viewAtTexel(t - ivec2(0, 1), size);
  vec3 dx = abs(r.z - c.z) < abs(c.z - l.z) ? r - c : c - l;
  vec3 dy = abs(u.z - c.z) < abs(c.z - b.z) ? u - c : c - b;
  vec3 n = normalize(cross(dx, dy));
  if (dot(n, c) > 0.0) n = -n;
  float cosSun = dot(n, toSun);
  // Only what faces up takes a contact shadow: the ground and the tops of blocks, never a leaf or a wall.
  float upward = smoothstep(${f(CONTACT.upwardFrom)}, ${f(CONTACT.upwardFull)}, dot(n, up));
  if (cosSun <= 0.0 || upward <= 0.0) return;
  // How far the depth steps from this pixel to the next: a sample must lie further behind than that to count.
  float stepZ = max(abs(dx.z), abs(dy.z));
  // How much of the sun the shadow map lets through: its cascade by depth, none past the last.
  float visible = 1.0;
  int i = -1;
  for (int k = ${CASCADES - 1}; k >= 0; k--) { if (splits[k] >= c.z) i = k; }
  if (i >= 0) {
    vec4 lc = cascades[i] * vec4(c, 1.0);
    vec3 cl = lc.xyz / lc.w;
    vec2 suv = cl.xy * 0.5 + 0.5;
    float sz = halfZ > 0.5 ? cl.z : cl.z * 0.5 + 0.5;
    if (suv.x >= 0.0 && suv.y >= 0.0 && suv.x <= 1.0 && suv.y <= 1.0) visible = texture(shadowMap, vec4(suv, float(i), clamp(sz, 0.0, 0.9999999)));
  }
  float direct = light.x * cosSun * visible;
  float total = direct + mix(light.z, light.y, 0.5 + 0.5 * dot(n, up));
  float share = total > 0.0 ? direct / total : 0.0;
  if (share <= 0.0) return;
  float offset = seed < 0.0 ? 0.5 : fract(52.9829189 * fract(dot(floor(vUV * screen), vec2(0.06711056, 0.00583715))) + seed);
  float occluded = 0.0;
  // The march's ends projected once: a straight line stays straight in clip space, and a sample's depth is its w.
  vec4 q0 = projection * vec4(c, 1.0);
  vec4 q1 = projection * vec4(c + toSun * ${f(CONTACT.lengthM)}, 1.0);
  for (int k = 0; k < ${CONTACT.steps}; k++) {
    vec4 q = mix(q0, q1, (float(k) + offset) / ${f(CONTACT.steps)});
    if (q.w <= 0.0) break;
    vec2 at = q.xy / q.w * 0.5 + 0.5;
    if (at.x < 0.0 || at.y < 0.0 || at.x > 1.0 || at.y > 1.0) break;
    float z = zFrom.y / (depthAt(ivec2(at * size)) * depthNdc.x + depthNdc.y - zFrom.x);
    float behind = q.w - z;
    if (behind > ${f(CONTACT.biasM)} + ${f(CONTACT.biasPerM)} * q.w + stepZ && behind < ${f(CONTACT.thicknessM)}) {
      float near = 1.0 - (float(k) + offset) / ${f(CONTACT.steps)};
      occluded = near * near;
      break;
    }
  }
  float fade = 1.0 - smoothstep(${f(CONTACT.fadeStartM)}, ${f(CONTACT.fadeEndM)}, c.z);
  gl_FragColor = vec4(colour.rgb * (1.0 - ${f(CONTACT.strength)} * occluded * share * fade * upward), colour.a);
}`;

// ---- WGSL (WebGPU): the same pass, in Babylon's WGSL post-process dialect. ----

const WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
var depthSampler: texture_depth_2d;
var shadowMapSampler: sampler_comparison;
var shadowMap: texture_depth_2d_array;
uniform lens: vec4f;
uniform projection: mat4x4f;
uniform cascades: array<mat4x4f, ${CASCADES}>;
uniform splits: vec4f;
uniform toSun: vec3f;
uniform up: vec3f;
uniform light: vec3f;
uniform depthNdc: vec2f;
uniform zFrom: vec2f;
uniform screen: vec2f;
uniform halfZ: f32;
uniform seed: f32;
fn depthAt(p: vec2i) -> f32 { return textureLoad(depthSampler, clamp(p, vec2i(0), vec2i(textureDimensions(depthSampler, 0)) - 1), 0); }
fn viewAt(at: vec2f, d: f32) -> vec3f {
  let z = uniforms.zFrom.y / (d * uniforms.depthNdc.x + uniforms.depthNdc.y - uniforms.zFrom.x);
  return vec3f((at * 2.0 - 1.0 - uniforms.lens.zw) * z / uniforms.lens.xy, z);
}
fn viewAtTexel(t: vec2i, size: vec2f) -> vec3f { return viewAt((vec2f(t) + 0.5) / size, depthAt(t)); }
fn shade(uv: vec2f) -> f32 {
  let size = vec2f(textureDimensions(depthSampler, 0));
  let t = vec2i(uv * size);
  let c = viewAtTexel(t, size);
  if (!(c.z > 0.0 && c.z < ${f(CONTACT.fadeEndM)})) { return 1.0; }
  let r = viewAtTexel(t + vec2i(1, 0), size);
  let l = viewAtTexel(t - vec2i(1, 0), size);
  let u = viewAtTexel(t + vec2i(0, 1), size);
  let b = viewAtTexel(t - vec2i(0, 1), size);
  var dx = c - l;
  if (abs(r.z - c.z) < abs(c.z - l.z)) { dx = r - c; }
  var dy = c - b;
  if (abs(u.z - c.z) < abs(c.z - b.z)) { dy = u - c; }
  var n = normalize(cross(dx, dy));
  if (dot(n, c) > 0.0) { n = -n; }
  let cosSun = dot(n, uniforms.toSun);
  let upward = smoothstep(${f(CONTACT.upwardFrom)}, ${f(CONTACT.upwardFull)}, dot(n, uniforms.up));
  if (cosSun <= 0.0 || upward <= 0.0) { return 1.0; }
  let stepZ = max(abs(dx.z), abs(dy.z));
  var visible = 1.0;
  var i = -1;
  for (var k = ${CASCADES - 1}; k >= 0; k--) { if (uniforms.splits[k] >= c.z) { i = k; } }
  if (i >= 0) {
    let lc = uniforms.cascades[i] * vec4f(c, 1.0);
    let cl = lc.xyz / lc.w;
    let suv = cl.xy * 0.5 + 0.5;
    var sz = cl.z * 0.5 + 0.5;
    if (uniforms.halfZ > 0.5) { sz = cl.z; }
    if (all(suv >= vec2f(0.0)) && all(suv <= vec2f(1.0))) { visible = textureSampleCompareLevel(shadowMap, shadowMapSampler, suv, i, clamp(sz, 0.0, 0.9999999)); }
  }
  let direct = uniforms.light.x * cosSun * visible;
  let total = direct + mix(uniforms.light.z, uniforms.light.y, 0.5 + 0.5 * dot(n, uniforms.up));
  var share = 0.0;
  if (total > 0.0) { share = direct / total; }
  if (share <= 0.0) { return 1.0; }
  var offset = 0.5;
  if (uniforms.seed >= 0.0) { offset = fract(52.9829189 * fract(dot(floor(uv * uniforms.screen), vec2f(0.06711056, 0.00583715))) + uniforms.seed); }
  var occluded = 0.0;
  let q0 = uniforms.projection * vec4f(c, 1.0);
  let q1 = uniforms.projection * vec4f(c + uniforms.toSun * ${f(CONTACT.lengthM)}, 1.0);
  for (var k = 0; k < ${CONTACT.steps}; k++) {
    let q = mix(q0, q1, (f32(k) + offset) / ${f(CONTACT.steps)});
    if (q.w <= 0.0) { break; }
    let at = q.xy / q.w * 0.5 + 0.5;
    if (any(at < vec2f(0.0)) || any(at > vec2f(1.0))) { break; }
    let z = uniforms.zFrom.y / (depthAt(vec2i(at * size)) * uniforms.depthNdc.x + uniforms.depthNdc.y - uniforms.zFrom.x);
    let behind = q.w - z;
    if (behind > ${f(CONTACT.biasM)} + ${f(CONTACT.biasPerM)} * q.w + stepZ && behind < ${f(CONTACT.thicknessM)}) {
      let near = 1.0 - (f32(k) + offset) / ${f(CONTACT.steps)};
      occluded = near * near;
      break;
    }
  }
  let fade = 1.0 - smoothstep(${f(CONTACT.fadeStartM)}, ${f(CONTACT.fadeEndM)}, c.z);
  return 1.0 - ${f(CONTACT.strength)} * occluded * share * fade * upward;
}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let colour = textureSampleLevel(textureSampler, textureSamplerSampler, input.vUV, 0.0);
  fragmentOutputs.color = vec4f(colour.rgb * shade(input.vUV), colour.a);
}`;

/** How bright a linear colour looks (Rec. 709). */
const luma = (c: { r: number; g: number; b: number }) => 0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b;

type Csm = ShadowGenerator & {
  numCascades: number;
  getCascadeTransformMatrix(i: number): Matrix | null;
  _viewSpaceFrustumsZ?: number[];
};

/** A cascaded generator with its map, and its light shining: something to refine. */
const usable = (g: ShadowGenerator | null): g is Csm => {
  if (!g || g.getClassName() !== 'CascadedShadowGenerator' || !g.getShadowMap()) return false;
  const light = g.getLight();
  return light.isEnabled() && light.intensity > 0;
};

export function createContactShadows(scene: Scene, camera: Camera, opts: { engineKind?: string }): ContactShadowsHandle {
  const engine = scene.getEngine();
  const wgsl = opts.engineKind === 'webgpu';
  const language = wgsl ? ShaderLanguage.WGSL : ShaderLanguage.GLSL;
  const store = wgsl ? ShaderStore.ShadersStoreWGSL : ShaderStore.ShadersStore;
  store[`${NAME}PixelShader`] ??= wgsl ? WGSL : GLSL;

  const pass = new PostProcess(NAME, NAME, {
    engine,
    size: 1,
    uniforms: ['lens', 'projection', 'cascades', 'splits', 'toSun', 'up', 'light', 'depthNdc', 'zFrom', 'screen', 'halfZ', 'seed'],
    samplers: ['depthSampler', 'shadowMap'],
    samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE,
    textureType: Constants.TEXTURETYPE_HALF_FLOAT,
    shaderLanguage: language,
  });
  let csm: Csm | null = null;
  let attached = false;
  let frame = 0;

  const ordering: Observer<Camera> = scene.onBeforeCameraRenderObservable.add((cam) => {
    if (cam === camera && attached) keepInOrder(camera);
  });
  pass.onActivateObservable.add(() => giveDepthIfFirst(camera, pass));

  const invView = new Matrix();
  const cascades = new Float32Array(16 * CASCADES);
  const toSun = new Vector3();
  const up = new Vector3(0, 1, 0);
  const sceneUp = new Vector3(0, 1, 0);
  pass.onApplyObservable.add((effect: Effect) => {
    const g = csm;
    const depth = sceneDepth(camera);
    if (depth) effect._bindTexture('depthSampler', depth);
    const projection = camera.getProjectionMatrix();
    const view = camera.getViewMatrix();
    view.invertToRef(invView);
    // The perspective's scale and its centre's offset (the anti-aliasing's jitter), to find points again from the depth.
    effect.setFloat4('lens', projection.m[0]!, projection.m[5]!, projection.m[8]!, projection.m[9]!);
    effect.setMatrix('projection', projection);
    // Each cascade from the eye's space, so the pass reads it with the points it finds again.
    const splits = [-1, -1, -1, -1];
    if (g) {
      const n = Math.min(CASCADES, g.numCascades);
      for (let i = 0; i < n; i++) {
        const m = g.getCascadeTransformMatrix(i);
        if (m) invView.multiply(m).copyToArray(cascades, i * 16);
        splits[i] = g._viewSpaceFrustumsZ?.[i] ?? -1;
      }
      const map = g.getShadowMap();
      if (map) effect.setDepthStencilTexture('shadowMap', map);
      const sun = g.getLight();
      Vector3.TransformNormalToRef((sun as unknown as { direction: Vector3 }).direction.negate(), view, toSun);
      toSun.normalize();
      const hemi = scene.lights.find((l) => l.getClassName() === 'HemisphericLight' && l.isEnabled()) as
        | (Scene['lights'][number] & { direction: Vector3; groundColor: { r: number; g: number; b: number } })
        | undefined;
      Vector3.TransformNormalToRef(hemi ? hemi.direction : sceneUp, view, up).normalize();
      effect.setFloat3('light', luma(sun.diffuse) * sun.intensity, hemi ? luma(hemi.diffuse) * hemi.intensity : 0, hemi ? luma(hemi.groundColor) * hemi.intensity : 0);
    }
    effect.setMatrices('cascades', cascades);
    effect.setFloat4('splits', splits[0]!, splits[1]!, splits[2]!, splits[3]!);
    effect.setFloat3('toSun', toSun.x, toSun.y, toSun.z);
    effect.setFloat3('up', up.x, up.y, up.z);
    const [a, b] = depthNdcOf(engine.isNDCHalfZRange);
    effect.setFloat2('depthNdc', a, b);
    effect.setFloat2('zFrom', projection.m[10]!, projection.m[14]!);
    effect.setFloat2('screen', pass.width, pass.height);
    effect.setFloat('halfZ', engine.isNDCHalfZRange ? 1 : 0);
    // Behind the anti-aliasing the samples move each frame and the frames blend them; without it they hold still.
    const blended = camera._postProcesses.some((p) => p?.name === 'planetTemporal');
    frame++;
    effect.setFloat('seed', blended ? (frame * 0.618034) % 1 : -1);
  });

  return {
    update({ shadows }) {
      csm = usable(shadows) ? shadows : null;
      const want = csm !== null;
      if (want === attached) return;
      attached = want;
      if (want) {
        camera.attachPostProcess(pass);
        keepInOrder(camera);
      } else camera.detachPostProcess(pass);
    },
    dispose() {
      scene.onBeforeCameraRenderObservable.remove(ordering);
      if (attached) camera.detachPostProcess(pass);
      attached = false;
      pass.dispose(camera);
    },
  };
}
