/**
 * Contact shadows on a planet, as numbers. The GPU pass
 * (contactShadowsChunk.ts) does this arithmetic per pixel, with these
 * constants.
 *
 * The sun's shadow map is too coarse, and too far biased, to draw the thin
 * dark line where a block, a plant or a person meets the ground. A pixel's
 * point is found again from the depth, and a short march toward the sun over
 * the depth asks whether anything drawn stands in the way: a sample that
 * lies behind what is drawn through it, by less than a block's thickness,
 * and by more than the depth's own step from one pixel to the next where the
 * march starts (on ground seen edge-on that step is long, and would shadow
 * the ground by itself).
 *
 * The darkness is a soft line, not a copy of what casts it: a hit counts
 * less the further along the march it is, so the shadow is darkest right at
 * the foot and fades within the march's length; and only a face turned up
 * (the ground, the top of a block) takes it, never a leaf or a wall.
 *
 * What is taken away is the sun's direct share of the pixel's light, and
 * only that: the sun's light on the face (by how squarely the face meets it,
 * and how much the sun's own shadow map lets through) over the sun's and the
 * sky's fill together. The fill is left as it was, and where the shadow map
 * already says shade there is nothing to take. The effect fades out with
 * distance, where a pixel is wider than the line it would draw.
 *
 * Pure: no Babylon, no DOM.
 */

export type Vec3 = [number, number, number];

export const CONTACT = {
  /** How far toward the sun the march looks, in metres: the most the line reaches from what casts it. */
  lengthM: 0.4,
  /** Samples along the march. */
  steps: 12,
  /** How far behind what is drawn a sample may lie and still be in its shadow, in metres: thicker, and a thin post shadows the ground far behind it. */
  thicknessM: 0.2,
  /** How far behind what is drawn a sample must lie to count, in metres, and more by its distance, for the depth's own precision. */
  biasM: 0.015,
  biasPerM: 0.002,
  /** Full strength out to this distance from the eye, in metres, and none from the second. */
  fadeStartM: 20,
  fadeEndM: 40,
  /** How much of the sun's direct share is taken where the march is blocked, 0 to 1. */
  strength: 0.7,
  /** How squarely a face must be turned up to take the shadow at all, and to take all of it: the cosine of its slope. */
  upwardFrom: 0.5,
  upwardFull: 0.85,
} as const;

/**
 * The sun's direct share of a face's light, 0 to 1: `sun` its light's
 * strength, `cosSun` how squarely it meets the face, `visible` how much of it
 * the sun's shadow map lets through (0 in shade), `fill` the sky's fill on
 * the face. Nothing for a face turned from the sun, nor with it down.
 */
export function directShare(sun: number, cosSun: number, visible: number, fill: number): number {
  const direct = Math.max(0, sun) * Math.max(0, cosSun) * Math.min(1, Math.max(0, visible));
  const all = direct + Math.max(0, fill);
  return all > 0 ? direct / all : 0;
}

/** How much of the effect is left at `depth` metres ahead of the eye: all of it near, none far. */
export function distanceFade(depth: number): number {
  const t = (depth - CONTACT.fadeStartM) / (CONTACT.fadeEndM - CONTACT.fadeStartM);
  const x = Math.min(1, Math.max(0, t));
  return 1 - x * x * (3 - 2 * x);
}

/** How much of the shadow a face takes by how squarely it is turned up (`cosUp`): none for a wall or a leaf, all for level ground. */
export function upwardWeight(cosUp: number): number {
  const t = (cosUp - CONTACT.upwardFrom) / (CONTACT.upwardFull - CONTACT.upwardFrom);
  const x = Math.min(1, Math.max(0, t));
  return x * x * (3 - 2 * x);
}

/**
 * The light left in a pixel, as a share of what it had: `occluded` the
 * march's darkness (contactOcclusion), `share` the sun's direct share,
 * `depth` its distance ahead, `cosUp` how squarely its face is turned up.
 */
export function contactShade(occluded: number, share: number, depth: number, cosUp = 1): number {
  return 1 - CONTACT.strength * occluded * share * distanceFade(depth) * upwardWeight(cosUp);
}

/** The sun's cascade a point `depth` metres ahead is in: the first whose far end is past it; -1 beyond the last. */
export function cascadeAt(depth: number, splits: readonly number[]): number {
  for (let i = 0; i < splits.length; i++) if (splits[i]! >= depth) return i;
  return -1;
}

/**
 * How dark the march from `start` (a point in the eye's space, metres, z
 * ahead) toward the sun (`toSun`, a unit vector in the same space) finds
 * it, 0 to 1: nothing if it meets nothing drawn, and the nearer the first
 * thing it meets, the darker, as the square of the share of the march left. `sceneZAt` gives the depth of what is
 * drawn through a point's place on the screen, null off it. `offset`, 0 to 1,
 * places the samples within their steps. `stepM` is how much the depth
 * changes from the start's pixel to the next, in metres.
 */
export function contactOcclusion(start: Vec3, toSun: Vec3, view: { sceneZAt(p: Vec3): number | null }, offset = 0.5, stepM = 0): number {
  for (let i = 0; i < CONTACT.steps; i++) {
    const t = (CONTACT.lengthM * (i + offset)) / CONTACT.steps;
    const p: Vec3 = [start[0] + toSun[0] * t, start[1] + toSun[1] * t, start[2] + toSun[2] * t];
    const z = view.sceneZAt(p);
    if (z === null) return 0;
    const behind = p[2] - z;
    if (behind > CONTACT.biasM + CONTACT.biasPerM * p[2] + stepM && behind < CONTACT.thicknessM) {
      const near = 1 - (i + offset) / CONTACT.steps;
      return near * near;
    }
  }
  return 0;
}
